def parse_version(text):
    return tuple(int(part) for part in text.split("."))

def outdated(required, installed):
    problems = []
    for name in sorted(required):
        need = required[name]
        have = installed.get(name)
        if have is None:
            problems.append(f"{name}: missing")
            continue
        a, b = parse_version(have), parse_version(need)
        width = max(len(a), len(b))
        a += (0,) * (width - len(a))
        b += (0,) * (width - len(b))
        if a < b:
            problems.append(f"{name}: {have} < {need}")
    return problems

print(outdated({"requests": "2.32", "pandas": "2.2"}, {"requests": "2.31.0"}))
